class _TTLCache(LinkedDict):
    """Internal cache implementation."""

    def __init__(self, maxsize, ttl, timer, typed=False):
        self._maxsize = maxsize
        self._ttl = ttl
        self._timer = timer
        self._typed = typed

    def get(self, func, *args, **kwargs):
