class LFUCache:
    def __init__(self, maxsize=128, typed=False):
        self.maxsize = maxsize
        self.typed = typed
        self.cache = collections.OrderedDict()
        self.counters = collections.OrderedDict()

    def __call__(self, func):
        def wrapped_func(*args, **kwargs):
            key = self._make_key(args, kwargs)
            if key in self.cache:
                self.counters[key] += 1
                return self.cache[key]
            else:
                if len(self.cache) >= self.maxsize:
                    self._remove_least_frequently_used()
                self.counters[key] = 1
                result = func(*args, **kwargs)
                self.cache[key] = result
                return result

        return wrapped_func

    def _make_key(self, args, kwargs):
        if self.typed:
            key = []
            for arg in args:
                key.append(type(arg))
            for key, value in kwargs.items():
                key.append(type(value))
            return tuple(key)
        else:
            return args + tuple(kwargs.items())

    def _remove_least_frequently_used(self):
        key, value = min(self.counters.items(), key=operator.itemgetter(1))
        del self.cache[key]
        del self.counters[key]

def lfu_cache(maxsize=128, typed=False):
    return LFUCache(maxsize, typed)

