def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of the in-style parameters.

    Parameters:
        sql (str or bytes): The SQL query.
        params (dict or list): The set of in-style parameters. If SQLParams.in_style is a named parameter style, then params must be a dict. If SQLParams.in_style is an ordinal parameter style, then params must be a list.
    Returns:
        A tuple containing:
            - The formatted SQL query (str or bytes).
            - The set of converted out-style parameters (dict or list).
    """

    if isinstance(sql, (str, bytes)):
        sql = str(sql)
    if isinstance(params, dict):
        params = list(params.items())
    elif isinstance(params, Sequence):
        params = list(params)
    else:
        raise TypeError(f"params must be a dict or list, not {type(params).__name__}")

    formatted_params = {}
    for i, param in enumerate(params, 1):
        if isinstance(param, str):
            escaped_param = escape(param, quote=False)
            sql = re.sub(f"\\{self.delimiter}{param}{self.delimiter}", f"{self.delimiter}?{escaped_param}{self.delimiter}?", sql, 1)
            formatted_params[param] = params[param]
        else:
            raise ValueError(f"Unsupported parameter type for ordinal parameter style: {type(param).__name__}")

    return (sql, formatted_params)
