    subst_exprs = []
    for expr in args:
        if isinstance(expr, OrExpr):
            if isinstance(expr.lhs, AndExpr):
                subst_exprs.append(expr.lhs.lhs)
        elif isinstance(expr, AndExpr):
            if isinstance(expr.lhs, OrExpr):
                subst_exprs.append(expr.lhs.lhs)

    processed_args = []
    for expr in args:
        if not isinstance(expr, AndExpr):
            processed_args.append(expr)
        else:
            for subst in subst_exprs:
                if subst in expr.args:
                    expr.args.remove(subst)
                    expr.args.append(AndExpr(subst, expr.rhs))
            processed_args.append(expr)

